#include "stdlib/blas/ext/base/ndarray/slast_index_of.h"
#include "stdlib/blas/ext/base/slast_index_of.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdint.h>

/**
* Returns the last index of a search element in a one-dimensional single-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the search element.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* -   If unable to find a search element, the function returns `-1`.
*
* @param arrays    list containing ndarrays
* @return          index
*/
CBLAS_INT stdlib_blas_ext_slast_index_of( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	float searchElement;
	stdlib_ndarray_get_float32( arrays[ 1 ], NULL, &searchElement );

	int32_t fromIndex;
	stdlib_ndarray_get_int32( arrays[ 2 ], NULL, &fromIndex );

	const CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );
	if ( fromIndex < 0 ) {
		fromIndex += N;
		if ( fromIndex < 0 ) {
			return -1;
		}
	} else if ( fromIndex >= N ) {
		fromIndex = (int32_t)( N-1 );
	}
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );

	const float *dataX = (const float *)stdlib_ndarray_data( x );
	return API_SUFFIX(stdlib_strided_slast_index_of_ndarray)( (CBLAS_INT)fromIndex+1, searchElement, dataX, strideX, offsetX );
}
